    @EventHandler( payloadType=CreateFXTradeEvent.class )
    public void handle( CreateFXTradeEvent event) {
	    LOGGER.info("handling CreateFXTradeEvent - " + event );
	    FXTrade entity = new FXTrade();
            entity.setFXTradeId( event.getFXTradeId() );
            entity.setTradeReference( event.getTradeReference() );
            entity.setTradeDate( event.getTradeDate() );
            entity.setSettlementDate( event.getSettlementDate() );
            entity.setAmountSold( event.getAmountSold() );
            entity.setAmountBought( event.getAmountBought() );
            entity.setRate( event.getRate() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllFXTrade( entity );
    }

