    /**
     * Method to retrieve the FXTrade via an FXTradePrimaryKey.
     * @param 	id Long
     * @return 	FXTrade
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public FXTrade handle( FindFXTradeQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getFXTradeId() );
    }
    
    /**
     * Method to retrieve a collection of all FXTrades
     *
     * @param	query	FindAllFXTradeQuery 
     * @return 	List<FXTrade> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<FXTrade> handle( FindAllFXTradeQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindFXTrade,
 * but only if the id matches
 *
 * @param		entity	FXTrade
 */
	protected void emitFindFXTrade( FXTrade entity ) {
		LOGGER.info("handling emitFindFXTrade" );
		
	    queryUpdateEmitter.emit(FindFXTradeQuery.class,
	                            query -> query.getFilter().getFXTradeId().equals(entity.getFXTradeId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllFXTrade
	 * 
	 * @param		entity	FXTrade
	 */
	protected void emitFindAllFXTrade( FXTrade entity ) {
		LOGGER.info("handling emitFindAllFXTrade" );
		
	    queryUpdateEmitter.emit(FindAllFXTradeQuery.class,
	                            query -> true,
	                            entity);
	}

